@Test
void throwExpectedException() {
    String root = System.getProperty("java.io.tmpdir");
    Path path = Paths.get(root, "not", "existed", "path");
    SeaTunnelRuntimeException exception = Assertions.assertThrows(SeaTunnelRuntimeException.class, () -> FileUtils.writeStringToFile(path.toString(), ""));
    Assertions.assertEquals("ErrorCode:[COMMON-22], ErrorDescription:[SeaTunnel write file '" + path + "' failed, because it not existed.]", exception.getMessage());
    SeaTunnelRuntimeException exception2 = Assertions.assertThrows(SeaTunnelRuntimeException.class, () -> FileUtils.readFileToStr(path));
    Assertions.assertEquals("ErrorCode:[COMMON-01], ErrorDescription:[SeaTunnel read file '" + path + "' failed.]", exception2.getMessage());
    Assertions.assertInstanceOf(NoSuchFileException.class, exception2.getCause());
    Assertions.assertEquals(path.toString(), exception2.getCause().getMessage());
    Path path2 = Paths.get(root, "not", "existed", "path2");
    SeaTunnelRuntimeException exception3 = Assertions.assertThrows(SeaTunnelRuntimeException.class, () -> FileUtils.getFileLineNumber(path2.toString()));
    Assertions.assertEquals("ErrorCode:[COMMON-01], ErrorDescription:[SeaTunnel read file '" + path2 + "' failed.]", exception3.getMessage());
