        }
        rowTypeInfo = new SeaTunnelRowType(keys.toArray(new String[0]), fieldTypes);
    }
    Assertions.assertNotNull(rowTypeInfo);
    Assertions.assertEquals(rowTypeInfo.getFieldType(0), BasicType.STRING_TYPE);
