@Test
public void testNumberWithNegativeScale() {
    BasicTypeDefine<Object> typeDefine = BasicTypeDefine.builder().name("test").columnType("number(38,-1)").dataType("number").precision(38L).scale(-1).build();
    Column column = OracleTypeConverter.INSTANCE.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    Assertions.assertEquals(new DecimalType(38, 0), column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.builder().name("test").columnType("number(5,-2)").dataType("number").precision(5L).scale(-2).build();
    column = OracleTypeConverter.INSTANCE.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    Assertions.assertEquals(BasicType.INT_TYPE, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.builder().name("test").columnType("number(9,-2)").dataType("number").precision(9L).scale(-2).build();
    column = OracleTypeConverter.INSTANCE.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    Assertions.assertEquals(BasicType.LONG_TYPE, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.builder().name("test").columnType("number(14,-11)").dataType("number").precision(14L).scale(-11).build();
    column = OracleTypeConverter.INSTANCE.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    Assertions.assertEquals(new DecimalType(25, 0), column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
}

