@Test
public void testPostgresGenerateSplitQuerySQL() {
    JdbcSourceConfig config = JdbcSourceConfig.builder().jdbcConnectionConfig(JdbcConnectionConfig.builder().url("jdbc:postgresql://localhost:5432/test").driverName("org.postgresql.Driver").build()).build();
    TableSchema tableSchema = TableSchema.builder().columns(Arrays.asList(PhysicalColumn.builder().name("id").sourceType("int4").dataType(BasicType.INT_TYPE).build())).build();
    DynamicChunkSplitter splitter = new DynamicChunkSplitter(config);
    JdbcSourceSplit split = new JdbcSourceSplit(TablePath.of("db1", "schema1", "table1"), "split1", null, "id", BasicType.INT_TYPE, 1, 10);
    String splitQuerySQL = splitter.createDynamicSplitQuerySQL(split, tableSchema);
    Assertions.assertEquals("SELECT * FROM \"db1\".\"schema1\".\"table1\" WHERE \"id\" >= ? AND NOT (\"id\" = ?) AND \"id\" <= ?", splitQuerySQL);
    split = new JdbcSourceSplit(TablePath.of("db1", "schema1", "table1"), "split1", "select * from table1", "id", BasicType.INT_TYPE, 1, 10);
    splitQuerySQL = splitter.createDynamicSplitQuerySQL(split, tableSchema);
    Assertions.assertEquals("SELECT * FROM (select * from table1) tmp WHERE \"id\" >= ? AND NOT (\"id\" = ?) AND \"id\" <= ?", splitQuerySQL);
    tableSchema = TableSchema.builder().columns(Arrays.asList(PhysicalColumn.builder().name("id").sourceType("uuid").dataType(BasicType.INT_TYPE).build())).build();
    split = new JdbcSourceSplit(TablePath.of("db1", "schema1", "table1"), "split1", "select * from table1", "id", BasicType.INT_TYPE, 1, 10);
    splitQuerySQL = splitter.createDynamicSplitQuerySQL(split, tableSchema);
    Assertions.assertEquals("SELECT * FROM (select * from table1) tmp WHERE \"id\"::text >= ? AND NOT (\"id\"::text = ?) AND \"id\"::text <= ?", splitQuerySQL);
}

@Test
public void testEfficientShardingThroughSampling() throws NoSuchMethodException {
