@Test
public void testConvertSqlWhereToPaimonPredicate() {
    String query = "SELECT * FROM table WHERE " + "char_col = 'a' AND " + "varchar_col = 'test' AND " + "boolean_col = 'true' AND " + "decimal_col = 123.45 AND " + "tinyint_col = 1 AND " + "smallint_col = 2 AND " + "int_col = 3 AND " + "bigint_col = 4 AND " + "float_col = 5.5 AND " + "double_col = 6.6 AND " + "date_col = '2022-01-01' AND " + "timestamp_col = '2022-01-01T12:00:00.123'";
    PlainSelect plainSelect = convertToPlainSelect(query);
    Predicate predicate = SqlToPaimonPredicateConverter.convertSqlWhereToPaimonPredicate(rowType, plainSelect);
    assertNotNull(predicate);
    PredicateBuilder builder = new PredicateBuilder(rowType);
    // Validate each part of the predicate
    Predicate expectedPredicate = PredicateBuilder.and(builder.equal(0, "a"), builder.equal(1, "test"), builder.equal(2, true), builder.equal(4, Decimal.fromBigDecimal(new BigDecimal("123.45"), 10, 2)), builder.equal(5, (byte) 1), builder.equal(6, (short) 2), builder.equal(7, 3), builder.equal(8, 4L), builder.equal(9, 5.5f), builder.equal(10, 6.6d), builder.equal(11, DateTimeUtils.toInternal(LocalDate.parse("2022-01-01"))), builder.equal(12, Timestamp.fromLocalDateTime(LocalDateTime.parse("2022-01-01T12:00:00.123"))));
    assertEquals(expectedPredicate.toString(), predicate.toString());
}

