@Test
public void testAllConnectorImplementFactoryWithUpToDateMethod() throws ClassNotFoundException {
    ServiceLoader<SeaTunnelSource> sources = ServiceLoader.load(SeaTunnelSource.class, Thread.currentThread().getContextClassLoader());
    Map<String, String> sourceWithSPI = new HashMap<>();
    Iterator<SeaTunnelSource> sourceIterator = sources.iterator();
    while (sourceIterator.hasNext()) {
        SeaTunnelSource source = sourceIterator.next();
        sourceWithSPI.put(source.getPluginName(), source.getClass().getName());
    }
    List<TableSourceFactory> sourceFactories = FactoryUtil.discoverFactories(Thread.currentThread().getContextClassLoader(), TableSourceFactory.class);
    // Some class can not get method, because it without some necessary jar dependency, like
    // hive-exec.jar. We need to check manually.
    List<String> blockList = new ArrayList<>();
    blockList.add("HiveSourceFactory");
    blockList.add("HiveSinkFactory");
    for (TableSourceFactory factory : sourceFactories) {
        if (ReflectionUtils.getDeclaredMethod(factory.getClass(), "createSource", TableSourceFactoryContext.class).isPresent() && !blockList.contains(factory.getClass().getSimpleName())) {
            Assertions.assertFalse(sourceWithSPI.containsKey(factory.factoryIdentifier()), "Please remove `@AutoService(SeaTunnelSource.class)` annotation in " + sourceWithSPI.get(factory.factoryIdentifier()));
            Class<? extends SeaTunnelSource> sourceClass = factory.getSourceClass();
            Optional<Method> prepare = ReflectionUtils.getDeclaredMethod(sourceClass, "prepare");
            Optional<Method> getProducedType = ReflectionUtils.getDeclaredMethod(sourceClass, "getProducedType");
            Optional<Method> getProducedCatalogTables = ReflectionUtils.getDeclaredMethod(sourceClass, "getProducedCatalogTables");
            Assertions.assertFalse(prepare.isPresent(), "Please remove `prepare` method, it will not be used any more");
            Assertions.assertFalse(getProducedType.isPresent(), "Please use `getProducedCatalogTables` method, do not implement `getProducedType` method in " + sourceClass.getSimpleName());
            Assertions.assertTrue(getProducedCatalogTables.isPresent(), "Please implement `getProducedCatalogTables` method in " + sourceClass.getSimpleName());
            log.info("Check source connector {} successfully", factory.getClass().getSimpleName());
        }
    }
    List<TableSinkFactory> sinkFactories = FactoryUtil.discoverFactories(Thread.currentThread().getContextClassLoader(), TableSinkFactory.class);
    ServiceLoader<SeaTunnelSink> sinks = ServiceLoader.load(SeaTunnelSink.class, Thread.currentThread().getContextClassLoader());
    Map<String, String> sinkWithSPI = new HashMap<>();
    Iterator<SeaTunnelSink> sinkIterator = sinks.iterator();
    while (sinkIterator.hasNext()) {
        SeaTunnelSink sink = sinkIterator.next();
        sinkWithSPI.put(sink.getPluginName(), sink.getClass().getName());
    }
    for (TableSinkFactory factory : sinkFactories) {
        String factoryName = factory.getClass().getSimpleName();
        if (ReflectionUtils.getDeclaredMethod(factory.getClass(), "createSink", TableSinkFactoryContext.class).isPresent() && !blockList.contains(factoryName)) {
            Assertions.assertFalse(sinkWithSPI.containsKey(factory.factoryIdentifier()), "Please remove `@AutoService(SeaTunnelSink.class)` annotation in " + sinkWithSPI.get(factory.factoryIdentifier()));
            Class<? extends SeaTunnelSink> sinkClass = (Class<? extends SeaTunnelSink>) Class.forName(factory.getClass().getName().replace(factoryName, factoryName.replace("Factory", "")));
            Optional<Method> prepare = ReflectionUtils.getDeclaredMethod(sinkClass, "prepare");
            Optional<Method> setTypeInfo = ReflectionUtils.getDeclaredMethod(sinkClass, "setTypeInfo", SeaTunnelRowType.class);
            Optional<Method> getConsumedType = ReflectionUtils.getDeclaredMethod(sinkClass, "getConsumedType");
            Assertions.assertFalse(prepare.isPresent(), "Please remove `prepare` method in " + sinkClass.getSimpleName());
            Assertions.assertFalse(setTypeInfo.isPresent(), "Please remove `setTypeInfo` method in " + sinkClass.getSimpleName());
            Assertions.assertFalse(getConsumedType.isPresent(), "Please remove `getConsumedType` method in " + sinkClass.getSimpleName());
            log.info("Check sink connector {} successfully", factory.getClass().getSimpleName());
            checkSupportMultiTableSink(sinkClass);
        }
    }
}

