@Test
public void testEventReport() throws IOException, InterruptedException {
    Container.ExecResult execResult = executeSeaTunnelJob("/fakesource_to_console.conf");
    Assertions.assertEquals(0, execResult.getExitCode());
    Thread.sleep(JobEventHttpReportHandler.REPORT_INTERVAL.toMillis());
    given().ignoreExceptions().await().atMost(60, TimeUnit.SECONDS).until(() -> mockWebServer.getRequestCount(), count -> count > 0);
    List<JsonNode> events = new ArrayList<>();
    for (int i = 0; i < mockWebServer.getRequestCount(); i++) {
        RecordedRequest request = mockWebServer.takeRequest();
        try (Buffer buffer = request.getBody()) {
            String body = buffer.readUtf8();
            ArrayNode arrayNode = (ArrayNode) JobEventHttpReportHandler.JSON_MAPPER.readTree(body);
            arrayNode.elements().forEachRemaining(jsonNode -> events.add(jsonNode));
        }
    }
    Assertions.assertEquals(8, events.size());
    Set<String> eventTypes = events.stream().map(e -> e.get("eventType").asText()).collect(Collectors.toSet());
    Assertions.assertTrue(eventTypes.containsAll(Arrays.asList(EventType.LIFECYCLE_ENUMERATOR_OPEN.name(), EventType.LIFECYCLE_ENUMERATOR_CLOSE.name(), EventType.LIFECYCLE_READER_OPEN.name(), EventType.LIFECYCLE_READER_CLOSE.name(), EventType.LIFECYCLE_WRITER_CLOSE.name())));
}

