        parameters = "{" + "\"jobId\":" + jobId2 + "," + "\"isStopWithSavePoint\":false}";
        given().body(parameters).post(http + container.getHost() + colon + container.getFirstMappedPort() + RestConstant.STOP_JOB_URL).then().statusCode(200).body("jobId", equalTo(jobId2));
