@Test
void testConfig() {
    // test both not set
    try {
        new FilterFieldTransform(ReadonlyConfig.fromMap(new HashMap<>()), catalogTable);
    } catch (Exception e) {
        Assertions.assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - There are unconfigured options, these options('include_fields', 'exclude_fields') are mutually exclusive, allowing only one set(\"[] for a set\") of options to be configured.", e.getMessage());
    }
    // test both include and exclude set
    try {
        new FilterFieldTransform(ReadonlyConfig.fromMap(new HashMap<String, Object>() {

            {
                put(FilterFieldTransformConfig.INCLUDE_FIELDS.key(), filterKeys);
                put(FilterFieldTransformConfig.EXCLUDE_FIELDS.key(), filterKeys);
            }
        }), catalogTable);
    } catch (Exception e) {
        Assertions.assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - These options('include_fields', 'exclude_fields') are mutually exclusive, allowing only one set(\"[] for a set\") of options to be configured.", e.getMessage());
    }
    // not exception should be thrown now
    new FilterFieldTransform(ReadonlyConfig.fromMap(new HashMap<String, Object>() {

        {
            put(FilterFieldTransformConfig.INCLUDE_FIELDS.key(), filterKeys);
        }
    }), catalogTable);
    new FilterFieldTransform(ReadonlyConfig.fromMap(new HashMap<String, Object>() {

        {
            put(FilterFieldTransformConfig.EXCLUDE_FIELDS.key(), filterKeys);
        }
    }), catalogTable);
}

@Test
void testInclude() {
    // default include
    Map<String, Object> configMap = new HashMap<>();
    configMap.put(FilterFieldTransformConfig.INCLUDE_FIELDS.key(), filterKeys);
    FilterFieldTransform filterFieldTransform = new FilterFieldTransform(ReadonlyConfig.fromMap(configMap), catalogTable);
    // test output schema
    TableSchema resultSchema = filterFieldTransform.transformTableSchema();
    Assertions.assertNotNull(resultSchema);
    Assertions.assertEquals(filterKeys.size(), resultSchema.getColumns().size());
    for (int i = 0; i < resultSchema.getColumns().size(); i++) {
        Assertions.assertEquals(filterKeys.get(i), resultSchema.getColumns().get(i).getName());
    }
    // test output row
    SeaTunnelRow input = new SeaTunnelRow(values);
    SeaTunnelRow output = filterFieldTransform.transformRow(input);
    Assertions.assertNotNull(output);
    Assertions.assertEquals(filterKeys.size(), output.getFields().length);
    for (int i = 0; i < resultSchema.getFieldNames().length; i++) {
        Integer originalIndex = catalogTable.getTableSchema().toPhysicalRowDataType().indexOf(resultSchema.getFieldNames()[i]);
        // test the row's field value
        Assertions.assertEquals(input.getFields()[originalIndex], output.getFields()[i]);
    }
}

@Test
void testExclude() {
    // exclude
    Map<String, Object> configMap = new HashMap<>();
    configMap.put(FilterFieldTransformConfig.EXCLUDE_FIELDS.key(), filterKeys);
    FilterFieldTransform filterFieldTransform = new FilterFieldTransform(ReadonlyConfig.fromMap(configMap), catalogTable);
    // test output schema
    TableSchema resultSchema = filterFieldTransform.transformTableSchema();
    Assertions.assertNotNull(resultSchema);
    Assertions.assertEquals(catalogTable.getTableSchema().getColumns().size() - filterKeys.size(), resultSchema.getColumns().size());
    for (int i = 0; i < catalogTable.getTableSchema().getFieldNames().length; i++) {
        if (!filterKeys.contains(catalogTable.getTableSchema().getFieldNames()[i])) {
            int finalI = i;
            Assertions.assertTrue(resultSchema.getColumns().stream().anyMatch(column -> column.getName().equals(catalogTable.getTableSchema().getFieldNames()[finalI])));
        }
    }
    // test output row
    SeaTunnelRow input = new SeaTunnelRow(values);
    SeaTunnelRow output = filterFieldTransform.transformRow(input);
    Assertions.assertNotNull(output);
    Assertions.assertEquals(catalogTable.getTableSchema().getColumns().size() - filterKeys.size(), output.getFields().length);
    for (int i = 0; i < output.getFields().length; i++) {
        if (!filterKeys.contains(catalogTable.getTableSchema().getFieldNames()[i])) {
            Integer originalIndex = catalogTable.getTableSchema().toPhysicalRowDataType().indexOf(catalogTable.getTableSchema().getFieldNames()[i]);
            // test the row's field value
            Assertions.assertEquals(input.getFields()[originalIndex], output.getFields()[i]);
        }
    }
}

